        {
            ArgumentNullException.ThrowIfNull(uiDoc);
            ArgumentNullException.ThrowIfNull(doc);

            // 1. Resolve Service
            var service = ServiceLocator.GetRequiredService<MaterialAssignmentExecutionService>();

